CREATE OR REPLACE PROCEDURE io.vt() RETURNS OBJECT LANGUAGE JAVA PACKAGES=('com.snowflake:snowpark:1.9.0') HANDLER='VariantTest.test' AS $$
import java.util.HashMap;
import java.util.Map;
import com.snowflake.snowpark_java.types.Variant;
import com.snowflake.snowpark_java.Session;

public class VariantTest {
  public String test(Session session) throws Exception {
    Map<String, Map<String, Object>> m = new HashMap<>();
    Map<String, Object> m2 = new HashMap<>();
    m2.put("c", 1);
    m.put("b", m2);
    Variant v = new Variant("{\"a\":1}");
    v = new Variant(m);
    return v.toString();
  }
}
$$

CREATE OR REPLACE PROCEDURE count_items() RETURNS VARCHAR LANGUAGE JAVA PACKAGES=('com.snowflake:snowpark:1.9.0') HANDLER='Counter.run' AS $$
import com.snowflake.snowpark_java.DataFrame;
import com.snowflake.snowpark_java.Row;
import com.snowflake.snowpark_java.Session;

public class Counter {
  public String run(Session session) {
    DataFrame df = session.sql("SELECT COUNT(*) AS CNT FROM public.items");
    Row[] rows = df.collect();
    if (rows.length > 0) {
      return "count=" + rows[0].getLong(0);
    }
    return "count=0";
  }
}
$$

CREATE OR REPLACE PROCEDURE greet(name VARCHAR) RETURNS VARCHAR LANGUAGE JAVA PACKAGES=('com.snowflake:snowpark:1.9.0') HANDLER='Greeter.greet' AS $$
import com.snowflake.snowpark_java.Session;

public class Greeter {
  public String greet(Session session, String name) {
    return "Hello, " + name + "!";
  }
}
$$
